CREATE TABLE IF NOT EXISTS "daily_closes" (
	"revenue_day" date PRIMARY KEY NOT NULL,
	"written_off_count" integer DEFAULT 0 NOT NULL,
	"written_off_zar" integer DEFAULT 0 NOT NULL,
	"reconciliation_status" text NOT NULL,
	"blocked_reason" text,
	"closed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"was_catch_up" boolean DEFAULT false NOT NULL,
	CONSTRAINT "daily_closes_written_off_count_nonneg" CHECK ("daily_closes"."written_off_count" >= 0),
	CONSTRAINT "daily_closes_written_off_zar_nonneg" CHECK ("daily_closes"."written_off_zar" >= 0),
	CONSTRAINT "daily_closes_status" CHECK ("daily_closes"."reconciliation_status" IN ('payments_matched', 'blocked')),
	CONSTRAINT "daily_closes_blocked_reason" CHECK (("daily_closes"."reconciliation_status" = 'blocked') = ("daily_closes"."blocked_reason" IS NOT NULL))
);
